import{_ as e,o as r,c as t,aA as n}from"./chunks/framework.BMzE2Z9R.js";const _=JSON.parse('{"title":"NARS各版实现 介绍","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"nars/impl/introduction.md","filePath":"nars/impl/introduction.md","lastUpdated":1778399398000}'),p={name:"nars/impl/introduction.md"};function o(s,a,i,l,c,d){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="nars各版实现-介绍" tabindex="-1">NARS各版实现 介绍 <a class="header-anchor" href="#nars各版实现-介绍" aria-label="Permalink to &quot;NARS各版实现 介绍&quot;">​</a></h1><p>在NARS的发展过程中，涌现了一大批研究者按照NARS的运作逻辑，用各种编程语言自己编写NARS核心。</p><p>由于版本多，加之理论难度和编程难度都对初学者入门造成了一定的阻碍，因此特地总结各个版本实现的简介和运行教程，让新手也能在自己计算设备上运行NARS，感受其实际效果。</p><p>索引页面请参照<a href="./">这里</a></p><h2 id="各版本总览" tabindex="-1">各版本总览 <a class="header-anchor" href="#各版本总览" aria-label="Permalink to &quot;各版本总览&quot;">​</a></h2><p>最经典的是王培教授使用Java语言编写实现的<a href="./impls/opennars.md/#opennars-1x">OpenNARS 1.5.8</a>。这一版实现了NAL1-6层，实现效果：稳定无变动。</p><p><a href="https://github.com/ARCJ137442" target="_blank" rel="noreferrer">ARCJ137442</a> 根据此版本魔改了一版实现，名为<a href="https://github.com/ARCJ137442/OpenNARS-158-dev" target="_blank" rel="noreferrer">OpenNARS-158-dev</a> ，并且在内补充了详尽的中文注释，可便于学习。</p><p>opennars经过发展后有3.0.4、3.1.1等几个大版本，</p><p>最后更换了python语言，由徐博文博士主持编写<a href="./impls/pynars">pynars (opennars 4.0)</a>。</p><p>4.0版本大改了控制机制，增加了多通道输入和对时间事件的感知与预测。整体实现由python实现，性能部分对接C++编写的cNARS作为运算单元，加快python代码运行速度。</p><ul><li>TODO：还有更多版本 见<a href="https://cis.temple.edu/tagit/#projects" target="_blank" rel="noreferrer">天普大学AGI团队</a>。</li></ul>',11)])])}const m=e(p,[["render",o]]);export{_ as __pageData,m as default};
